13	 */
14	@RestControllerAdvice
15	public class GlobalExceptionHandler {
16	
17	    @ExceptionHandler(BusinessException.class)
18	    public ResponseEntity<ErrorResponse> handleBusiness(BusinessException ex) {
19	        return ResponseEntity.status(ex.getHttpStatus())
20	                .body(new ErrorResponse(ex.getError(), ex.getMessage()));
21	    }
22	
23	    @ExceptionHandler(MethodArgumentNotValidException.class)
24	    public ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
25	        String message = ex.getBindingResult().getFieldErrors().stream()
26	                .map(error -> error.getField() + " " + error.getDefaultMessage())
