    /** 将服务返回体（含幂等重放的 Map）统一转换为视图。 */
    protected ReviewView asView(ServiceResult result) {
        return jsonSupport.convertValue(result.body(), ReviewView.class) == null
                ? null
                : jsonSupport.convertValue(result.body(), ReviewView.class);
    }
