 */
public record CustomsRegisterRequest(
        @NotBlank String requestId,
        @NotBlank String customsNo,
        @NotBlank String enterpriseName,
        @NotBlank String productName,
        @NotNull Instant validUntil,
        @Positive int totalQuantity,
        @NotNull Instant at
) {
}

