/** 等待并发首事务的幂等记录定稿（http_status 非 0）；记录消失（失败回滚）返回 null。 */
private com.example.starter.domain.IdempotencyRecord awaitFinalizedOrGone(String requestId) {
    for (int i = 0; i < 300; i++) {
        var record = idempotencyRepository.find(requestId);
        if (record != null && record.getHttpStatus() != 0) {
            return record;
        }
        if (record == null && i > 0) {
            // 再确认一轮，避免首事务恰好尚未插入占位的误判。
            var again = idempotencyRepository.find(requestId);
            if (again == null) {
                return null;
            }
        }
        try {
            Thread.sleep(10);
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
            throw new BusinessException(500, "IDEMPOTENCY_WAIT_INTERRUPTED", "等待首次请求结果时被中断");
        }
    }
    var last = idempotencyRepository.find(requestId);
    return last != null && last.getHttpStatus() != 0 ? last : null;
}

