            throw new BusinessException(500, "IDEMPOTENCY_WAIT_INTERRUPTED", "等待首次请求结果时被中断");
        }
    }
    throw new BusinessException(500, "IDEMPOTENCY_RECORD_NOT_FINALIZED",
            "并发首请求长时间未定稿: " + requestId);
}

