    void amendOnlyIncreasesTotalAndDoesNotChangeHistory() {
        customsService.register(registerRequest("reg-am", "CI-AM", 100));
        makeIssueable("d-am", "B-AM");
        customsService.bind(bindRequest("bind-am", "CI-AM", "B-AM", 30, 1));

